import '../domain/models/user_model.dart';

class StudentRecord {
  final String studentNo;
  final String tcFirst5;
  final String fullName;
  final String email;
  final int grade; // 1 (26 girişli) or 2 (25, 24, 23 girişli)
  final String groupId; // 'BGT1' or 'BGT2'
  final String program;

  const StudentRecord({
    required this.studentNo,
    required this.tcFirst5,
    required this.fullName,
    required this.email,
    required this.grade,
    required this.groupId,
    required this.program,
  });

  UserModel toUserModel() {
    return UserModel(
      uid: 'student_$studentNo',
      email: email,
      displayName: fullName,
      role: UserRole.student,
      groupId: groupId,
      studentNo: studentNo,
      grade: grade,
      isDemo: false,
    );
  }
}

